"""Verify generated bytes against the same frozen report; this is not evidence/visual certification."""
import argparse
import hashlib
from html.parser import HTMLParser
import json
from pathlib import Path
import re
import subprocess
import tempfile
import zipfile
import xml.etree.ElementTree as ET
from generate_report import markdown_document
from report_schema import read_report, parse_formats, public_texts

MAX_FILE_BYTES = 32 * 1024 * 1024


def bounded_read(path, limit=MAX_FILE_BYTES):
    if not path.is_file() or path.stat().st_size == 0 or path.stat().st_size > limit:
        raise ValueError(f'Missing, empty or oversized output: {path.name}')
    return path.read_bytes()


class PublicHTML(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.ignored = 0
        self.body = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if any(key.lower().startswith('on') for key in attributes) or tag in ('iframe', 'object', 'embed'):
            raise ValueError('Executable report HTML is not allowed')
        if tag == 'script' and not (attributes.get('type') == 'application/json' and attributes.get('id') in ('sourceweft-font-evidence', 'sourceweft-font-licenses')):
            raise ValueError('Executable report HTML is not allowed')
        if tag == 'body':
            self.body = True
        if tag in ('script', 'style'):
            self.ignored += 1

    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.ignored -= 1
        if tag == 'body':
            self.body = False

    def handle_data(self, value):
        if self.body and not self.ignored:
            self.parts.append(value)


def normalized(value):
    return re.sub(r'\s+', '', value)


def assert_content(report, extracted, label, ordered=True):
    actual = normalized(extracted)
    if ordered:
        expected_all = normalized(' '.join(public_texts(report)))
        if actual != expected_all:
            raise ValueError(f'{label} full public text differs from the frozen report')
        return
    position = 0
    for expected in public_texts(report):
        value = normalized(expected)
        found = actual.find(value, position if ordered else 0)
        if found < 0:
            raise ValueError(f'{label} content differs at: {expected[:100]}')
        if ordered:
            position = found + len(value)


def docx_text(path):
    bounded_read(path)
    with zipfile.ZipFile(path) as archive:
        entries = archive.infolist()
        if len(entries) > 2000 or sum(item.file_size for item in entries) > 100 * 1024 * 1024:
            raise ValueError('DOCX archive exceeds expansion bounds')
        names = [entry.filename for entry in entries]
        if len(names) != len(set(names)):
            raise ValueError('Duplicate DOCX archive member')
        required = {'[Content_Types].xml', '_rels/.rels', 'word/document.xml'}
        if not required.issubset(names):
            raise ValueError('Missing required DOCX package parts')
        if archive.testzip() is not None:
            raise ValueError('DOCX archive CRC failed')
        def package_xml(name):
            data = archive.read(name)
            if b'<!DOCTYPE' in data or b'<!ENTITY' in data:
                raise ValueError('Unexpected DOCX XML declarations')
            return ET.fromstring(data)
        types = package_xml('[Content_Types].xml')
        content_ns = '{http://schemas.openxmlformats.org/package/2006/content-types}'
        if types.tag != content_ns + 'Types' or not any(
            entry.get('PartName') == '/word/document.xml' and
            entry.get('ContentType') == 'application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml'
            for entry in types.findall(content_ns + 'Override')
        ):
            raise ValueError('Invalid DOCX main document content type')
        relationships = package_xml('_rels/.rels')
        relation_ns = '{http://schemas.openxmlformats.org/package/2006/relationships}'
        if relationships.tag != relation_ns + 'Relationships' or not any(
            entry.get('Type') == 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument' and
            entry.get('Target') in ('word/document.xml', '/word/document.xml') and
            entry.get('TargetMode', 'Internal') == 'Internal'
            for entry in relationships.findall(relation_ns + 'Relationship')
        ):
            raise ValueError('Invalid DOCX officeDocument relationship')
        info = archive.getinfo('word/document.xml')
        if info.file_size > MAX_FILE_BYTES:
            raise ValueError('DOCX XML exceeds limit')
        xml = archive.read(info)
        namespace = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
        for entry in entries:
            if entry.filename.startswith(('word/header', 'word/footer', 'word/comments', 'word/footnotes', 'word/endnotes')) and entry.filename.endswith('.xml'):
                extra = archive.read(entry)
                if b'<!DOCTYPE' in extra or b'<!ENTITY' in extra:
                    raise ValueError('Unexpected DOCX XML declarations')
                if any((node.text or '').strip() for node in ET.fromstring(extra).iter(namespace + 't')):
                    raise ValueError('Unexpected text outside the report DOCX body')
    if b'<!DOCTYPE' in xml or b'<!ENTITY' in xml:
        raise ValueError('Unexpected DOCX XML declarations')
    root = ET.fromstring(xml)
    namespace = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
    return '\n'.join(''.join(t.text or '' for t in p.iter(namespace + 't')) for p in root.iter(namespace + 'p'))


def verify(source, directory, formats):
    report = read_report(source)
    directory = Path(directory)
    # The published editing source must be the same validated semantic input.
    if read_report(directory / 'report.source.json') != report:
        raise ValueError('Private source does not match the input version')
    files = []
    checks = []
    for fmt in formats:
        path = directory / ('report.' + fmt)
        data = bounded_read(path)
        if fmt == 'html':
            parser = PublicHTML()
            parser.feed(data.decode('utf-8'))
            assert_content(report, '\n'.join(parser.parts), 'HTML')
            checks.append('HTML reading order and all public text')
        elif fmt == 'md':
            if data.decode('utf-8') != markdown_document(report):
                raise ValueError('Markdown differs from the frozen report')
            checks.append('Markdown exact deterministic text')
        elif fmt == 'docx':
            assert_content(report, docx_text(path), 'DOCX')
            checks.append('DOCX package and public reading order')
        else:
            if not data.startswith(b'%PDF-'):
                raise ValueError('Invalid PDF signature')
            with tempfile.TemporaryDirectory(prefix='sourceweft-report-verify-') as temporary:
                extracted = Path(temporary) / 'content.txt'
                subprocess.run(['pdftotext', '-layout', str(path.resolve()), str(extracted)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30, check=True)
                # PDF table layout may reorder cells on wrapped lines. Check all
                # expected text/numbers, while ordered checks cover other formats.
                assert_content(report, bounded_read(extracted).decode('utf-8'), 'PDF', ordered=False)
            checks.append('PDF extraction and all public text/numbers; visual review remains required')
        files.append({'fileName': path.name, 'byteLength': len(data), 'contentDigest': 'sha256:' + hashlib.sha256(data).hexdigest()})
    unexpected = [f'report.{fmt}' for fmt in ('md', 'docx', 'pdf') if fmt not in formats and (directory / f'report.{fmt}').exists()]
    if unexpected:
        raise ValueError('Unrequested deliverables present: ' + ', '.join(unexpected))
    return {'passed': True, 'checks': checks, 'files': files, 'evidenceAuthenticated': False, 'visualReview': 'not_run'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', required=True)
    parser.add_argument('--output-dir', required=True)
    parser.add_argument('--formats', default='html,md')
    args = parser.parse_args()
    print(json.dumps(verify(args.source, args.output_dir, parse_formats(args.formats)), ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()
